static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ProductReductionOverADimensionCustomTilingData tiling;
    const gert::Shape* in_shape = context->GetInputShape(0);
    auto origin_shape = in_shape->GetOriginShape();
    int64_t dims = origin_shape.GetDimNum();
    if (dims != 3) {
        return ge::GRAPH_FAILED;
    }
    uint32_t B = static_cast<uint32_t>(origin_shape.GetDim(0));
    uint32_t M = static_cast<uint32_t>(origin_shape.GetDim(1));
    uint32_t N = static_cast<uint32_t>(origin_shape.GetDim(2));

    uint32_t totalLength = static_cast<uint32_t>(origin_shape.GetShapeSize());
    context->SetBlockDim(BLOCK_DIM);

    tiling.set_totalLength(totalLength);
    tiling.set_batch(B);
    tiling.set_reduceLen(M);
    tiling.set_lastAxis(N);
    tiling.set_tileNum(TILE_NUM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

